def copy_row(label,value,c):
 return '<div class="payment-detail-row"><dt>'+E(label)+'</dt><dd><code>'+E(value)+'</code><button type="button" data-pay-copy="'+E(value,quote=True)+'">'+c['copy']+'</button></dd></div>'
